cd ~ && H=/efs/home/__USER__; for i in $(seq 1 12); do ls /efs/home >/dev/null 2>&1; [ -e "$H" ] && break; sleep 2; done; UID_NUM=$(stat -c %u "$H" 2>/dev/null); GID_NUM=$(stat -c %g "$H" 2>/dev/null); if [ -z "$UID_NUM" ] || [ -z "$GID_NUM" ]; then echo "secondary: ERROR /efs/home/__USER__ not visible from this bastion (do both bastions mount the same EFS?)"; else groupadd -g "$GID_NUM" __USER__ 2>/dev/null || true; useradd -u "$UID_NUM" -g "$GID_NUM" -M -d "$H" __USER__ 2>/dev/null || true; fi; id __USER__ >/dev/null 2>&1 && echo "secondary: __USER__ ready" || echo "secondary: FAILED to create __USER__"